//! Lucide icons rendered as inline SVG, byte-for-byte the markup lucide-react produced.
//! The path data lives in `icons_data.rs` (generated by scripts/gen-icons.mjs).

use leptos::prelude::*;

#[path = "../icons_data.rs"]
mod data;

fn lookup(name: &str) -> (&'static str, &'static str) {
    data::ICONS
        .iter()
        .find(|(n, _, _)| *n == name)
        .map(|(_, class, inner)| (*class, *inner))
        .unwrap_or_else(|| {
            debug_assert!(false, "unknown icon: {name}");
            ("lucide", "")
        })
}

/// `<Icon name="ArrowRight" class="size-4"/>`; `class` may be static or reactive.
#[component]
pub fn Icon(name: &'static str, #[prop(into, optional)] class: Signal<String>) -> impl IntoView {
    let (lucide, inner) = lookup(name);
    view! {
        <svg
            xmlns="http://www.w3.org/2000/svg"
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
            stroke-linejoin="round"
            class=move || {
                let c = class.get();
                if c.is_empty() { lucide.to_string() } else { format!("{lucide} {c}") }
            }
            aria-hidden="true"
            inner_html=inner
        ></svg>
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_icon_used_in_sources_exists() {
        let names: Vec<&str> = super::data::ICONS.iter().map(|(n, _, _)| *n).collect();
        let re = regex_lite::Regex::new(r#"(?:Icon name|icon)\s*[=:]\s*"([A-Za-z0-9]+)""#).unwrap();
        let mut stack = vec![std::path::PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/src"))];
        while let Some(p) = stack.pop() {
            for e in std::fs::read_dir(&p).unwrap() {
                let path = e.unwrap().path();
                if path.is_dir() {
                    stack.push(path);
                } else if path.extension().is_some_and(|x| x == "rs") {
                    let src = std::fs::read_to_string(&path).unwrap();
                    for c in re.captures_iter(&src) {
                        assert!(names.contains(&&c[1]), "unknown icon {} in {}", &c[1], path.display());
                    }
                }
            }
        }
    }
}
